import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const env = config.get("env") ?? "dev";
const region = config.get("region") ?? "us-east-1";

// Store this with:
// pulumi config set --secret dbPassword '<password>'
const dbPassword = config.requireSecret("dbPassword");

const provider = new aws.Provider("aws-provider", {
    region: region as aws.Region,
});

// S3 bucket
const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: {
        enabled: true,
    },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
    tags: {
        Environment: env,
        Project: "myapp",
    },
}, { provider });

new aws.s3.BucketPublicAccessBlock("app-bucket-public-access", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
}, { provider });

// Transform the Output with apply; do not await it.
const bucketUrl = bucket.bucket.apply(
    name => `https://${name}.s3.${region}.amazonaws.com`,
);

// RDS instance
const isProd = env === "prod";

const db = new aws.rds.Instance("app-db", {
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    engineVersion: "16.1",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app_user",
    password: dbPassword,

    multiAz: isProd,
    storageEncrypted: isProd,
    publiclyAccessible: false,
    backupRetentionPeriod: 7,
    deletionProtection: true,

    // Required if the protected resource is later intentionally destroyed.
    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `myapp-${env}-final-snapshot`,

    tags: {
        Environment: env,
        Project: "myapp",
    },
}, { provider });

export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

Configure each stack independently:

```bash
pulumi stack select dev
pulumi config set env dev
pulumi config set region us-east-1
pulumi config set --secret dbPassword '<dev-password>'

pulumi stack select prod
pulumi config set env prod
pulumi config set region us-east-1
pulumi config set --secret dbPassword '<prod-password>'
```

The key fixes are:

- Replace `await` on an `Output` with `.apply(...)`.
- Export an `Output<string>`, not the result of an `async` function.
- Replace the plaintext `pulumi.output(...)` password with `config.requireSecret(...)`.
- Use the bucket name rather than its ARN when constructing the S3 URL.
